testo:
{
 "genere": "prevedi",
 "titolo": "Cosa restituisce?",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run():
	var current_health: int = 25
	var amount: int = 40
	var new_health := maxi(0, current_health - amount)
	return new_health
",
   "domanda": "Quanto vale `new_health` alla fine?",
   "spiegazione": "`25 - 40` fa `-15`. `maxi(0, -15)` restituisce `0` perché sceglie il valore più alto tra zero e il numero negativo, impedendo alla vita di scendere sotto lo zero."
  },
  {
   "codice": "extends RefCounted


func run():
	var target := Vector2(100, 100)
	var global_pos := Vector2(100, 100)
	var dir := (target - global_pos).normalized()
	if dir == Vector2.ZERO:
		dir = Vector2.RIGHT
	return dir
",
   "domanda": "Che Vector2 restituisce `run()`?",
   "spiegazione": "`target - global_pos` dà un vettore zero `Vector2(0, 0)`. La normalizzazione restituisce sempre zero. Poiché `dir == Vector2.ZERO` è vero, la direzione viene corretta in `Vector2.RIGHT` (cioè `Vector2(1, 0)`)."
  },
  {
   "codice": "extends RefCounted


func run():
	var shoot_timer: float = 0.5
	var delta: float = 0.3
	shoot_timer -= delta
	var can_shoot := shoot_timer <= 0.0
	return can_shoot
",
   "domanda": "Che valore booleano restituisce `run()`?",
   "spiegazione": "`0.5 - 0.3` fa `0.2`. La condizione `0.2 <= 0.0` è falsa, quindi `can_shoot` è `false` (il timer non è ancora scaduto)."
  },
  {
   "codice": "extends RefCounted


func run():
	var position := Vector2(10, 20)
	var direction := Vector2(0, 1)
	var speed := 250.0
	var delta := 0.02
	position += direction * speed * delta
	return position
",
   "domanda": "Quanto vale `position` alla fine?",
   "spiegazione": "`direction * speed` fa `Vector2(0, 250)`. Moltiplicato per `0.02` fa `Vector2(0, 5)`. Sommato a `Vector2(10, 20)` dà `Vector2(10, 25)`."
  },
  {
   "codice": "extends RefCounted


func run():
	var current_health: int = 10
	var amount: int = 10
	var is_dead := false
	current_health = maxi(0, current_health - amount)
	if current_health == 0:
		is_dead = true
	return is_dead
",
   "domanda": "Che valore restituisce `run()`?",
   "spiegazione": "`10 - 10` fa `0`. `maxi(0, 0)` restituisce `0`. Poiché la condizione `current_health == 0` è vera, la variabile `is_dead` diventa `true`."
  }
 ]
}
